-- Port of Catalog's InitialSchema migration. Every table is the original's,
-- column for column. Track's GenreId and MediaTypeId are plain indexed ids:
-- Genre and MediaType belong to Administration, so no foreign key crosses
-- into that schema (ADR-0006, ADR-0007).

CREATE TABLE catalog."Artist" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Name" varchar(120) NULL,
    CONSTRAINT "PK_Artist" PRIMARY KEY ("Id")
);

CREATE TABLE catalog."Playlist" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Name" varchar(120) NULL,
    CONSTRAINT "PK_Playlist" PRIMARY KEY ("Id")
);

CREATE TABLE catalog."Album" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Title" varchar(160) NULL,
    "ArtistId" integer NULL,
    CONSTRAINT "PK_Album" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Album_Artist_ArtistId" FOREIGN KEY ("ArtistId") REFERENCES catalog."Artist" ("Id")
);

CREATE TABLE catalog."Track" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Name" varchar(200) NULL,
    "AlbumId" integer NULL,
    "MediaTypeId" integer NULL,
    "GenreId" integer NULL,
    "Composer" varchar(220) NULL,
    "Milliseconds" integer NULL,
    "Bytes" integer NULL,
    "UnitPrice" numeric(10,2) NULL,
    CONSTRAINT "PK_Track" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Track_Album_AlbumId" FOREIGN KEY ("AlbumId") REFERENCES catalog."Album" ("Id")
);

CREATE TABLE catalog."PlaylistTrack" (
    "PlaylistId" integer NOT NULL,
    "TrackId" integer NOT NULL,
    CONSTRAINT "PK_PlaylistTrack" PRIMARY KEY ("PlaylistId", "TrackId"),
    CONSTRAINT "FK_PlaylistTrack_Playlist_PlaylistId" FOREIGN KEY ("PlaylistId") REFERENCES catalog."Playlist" ("Id"),
    CONSTRAINT "FK_PlaylistTrack_Track_TrackId" FOREIGN KEY ("TrackId") REFERENCES catalog."Track" ("Id")
);

CREATE INDEX "IX_Album_ArtistId" ON catalog."Album" ("ArtistId");
CREATE INDEX "IX_PlaylistTrack_TrackId" ON catalog."PlaylistTrack" ("TrackId");
CREATE INDEX "IX_Track_AlbumId" ON catalog."Track" ("AlbumId");
CREATE INDEX "IX_Track_GenreId" ON catalog."Track" ("GenreId");
CREATE INDEX "IX_Track_MediaTypeId" ON catalog."Track" ("MediaTypeId");
